class Solution:
    def maxSubarrayLength(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            for j in range(n - 1, i, -1):
                if nums[j] < nums[i]:
                    ans = max(ans, j - i + 1)
                    break
        return ans

