class Solution:
    def maxSubarrayLength(self, nums: List[int]) -> int:
        pairs = sorted((v, i) for i, v in enumerate(nums))
        ans = 0
        maxIdx = -1
        i = 0
        while i < len(pairs):
            v = pairs[i][0]
            j = i
            while j < len(pairs) and pairs[j][0] == v:
                if maxIdx >= 0:
                    ans = max(ans, maxIdx - pairs[j][1] + 1)
                j += 1
            for t in range(i, j):
                maxIdx = max(maxIdx, pairs[t][1])
            i = j
        return ans

