int maxSubarrayLength(vector<int>& nums) {
    int n = nums.size();
    vector<pair<int,int>> p(n);
    for (int i = 0; i < n; i++) p[i] = {nums[i], i};
    sort(p.begin(), p.end());
    int ans = 0, maxIdx = -1;
    int i = 0;
    while (i < n) {
        int v = p[i].first, j = i;
        while (j < n && p[j].first == v) {
            if (maxIdx >= 0) ans = max(ans, maxIdx - p[j].second + 1);
            j++;
        }
        for (int t = i; t < j; t++) maxIdx = max(maxIdx, p[t].second);
        i = j;
    }
    return ans;
}

