public int maxSubarrayLength(int[] nums) {
    int n = nums.length;
    int[][] p = new int[n][2];
    for (int i = 0; i < n; i++) { p[i][0] = nums[i]; p[i][1] = i; }
    Arrays.sort(p, (a, b) -> Integer.compare(a[0], b[0]));
    int ans = 0, maxIdx = -1, i = 0;
    while (i < n) {
        int v = p[i][0], j = i;
        while (j < n && p[j][0] == v) {
            if (maxIdx >= 0) ans = Math.max(ans, maxIdx - p[j][1] + 1);
            j++;
        }
        for (int t = i; t < j; t++) maxIdx = Math.max(maxIdx, p[t][1]);
        i = j;
    }
    return ans;
}

