    const pairs = nums.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]);
    let ans = 0, maxIdx = -1, i = 0;
    while (i < pairs.length) {
        const v = pairs[i][0];
        let j = i;
        while (j < pairs.length && pairs[j][0] === v) {
            if (maxIdx >= 0) ans = Math.max(ans, maxIdx - pairs[j][1] + 1);
            j++;
        }
        for (let t = i; t < j; t++) maxIdx = Math.max(maxIdx, pairs[t][1]);
        i = j;
    }
    return ans;
};
